package apiserver

import (
	"net/http"

	"github.com/mandacode-labs/mdrive/api"
)

// OpenAPIPassthrough serves the bundled OpenAPI 3.1 spec at
// /openapi.json and forwards every other request to next.
//
// Mounted in the middleware chain BEFORE the auth wrapper so the
// spec is reachable without a session — a public document
// describing the API surface, not a secret. The spec is embedded
// at compile time from api/openapi.bundled.json (generated by
// `make gen-api` / `npx swagger-cli bundle`).
func OpenAPIPassthrough(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/openapi.json" {
			next.ServeHTTP(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.Header().Set("Cache-Control", "public, max-age=300")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(api.Spec)
	})
}